weight_reduction.live_full:
weight_reduction(){
    const hp3=vd('hp3',425), wt3=vd('wt3',3420), red=vd('red',100);
    const newWt3 = wt3 - red;
    const gain = ([hp3,wt3,red].every(Number.isFinite) && newWt3 > 0) ? +(hp3*(red/newWt3)).toFixed(1) : NaN;
    return `${headerHTML('Weight Reduction HP Gain','Every pound saved is worth HP at the track. Uses the formula: HP Gain = HP × (weight reduction / new weight).')}
    <div class="calc-body">
      ${field('Current Horsepower','hp3',425,'HP')}
      ${field('Current Vehicle Weight','wt3',3420,getU('weight'))}
      ${field('Weight to Remove','red',100,getU('weight'))}
      ${resultHTML('Equivalent HP Gain', gain, 'HP', true)}
    </div>${calcFooter('Weight Reduction')}`;
  }

