static_compression.live_full:
static_compression(){
    const bore2=vd('bore2',4.2500), stroke2=vd('str2',3.7500), chamber=vd('dcv',64.000), gasket=vd('hgv',8.000), piston=vd('pv2',0.000);
    const sweptIn3=(Math.PI/4)*Math.pow(bore2,2)*stroke2;
    const sweptCC=sweptIn3*16.387064;
    const clearance=chamber+gasket-piston;
    const valid=bore2>0&&stroke2>0&&chamber>=0&&gasket>=0&&clearance>0;
    const ratio=valid?+((sweptCC+clearance)/clearance).toFixed(3):0;
    return `${headerHTML('Static Compression Ratio','All chamber, gasket and piston volumes are normalized to cc before calculation. CR = (swept volume + clearance volume) / clearance volume. Piston volume is entered as positive for dome volume (subtracts from clearance) and negative for a dish (adds to clearance).')}
    <div class="calc-body">
      ${field('Bore','bore2',4.2500,getU('length'))}
      ${field('Stroke','str2',3.7500,getU('length'))}
      ${field('Chamber Volume','dcv',64.000,'cc')}
      ${field('Head Gasket Volume','hgv',8.000,'cc')}
      ${field('Piston Volume (+dome / −dish)','pv2',0.000,'cc')}
      ${valid?multiResult([{label:'Swept Volume',value:sweptCC,unit:'cc'},{label:'Clearance Volume',value:clearance,unit:'cc'},{label:'Static Compression Ratio',value:ratio,unit:':1'}]):`<div class="result-box"><div class="result-value">Invalid compression-volume inputs</div><div class="help-note">Clearance volume must be greater than zero.</div></div>`}
    </div>${calcFooter('Compression Ratio')}`;
  }

