crawl_ratio_tire.live_full:
crawl_ratio_tire(){
    /* WAVE 1 P0 (off-road brief, Sept 2026). Tire-adjusted effective crawl ratio.
       Larger tires raise the effective final drive, reducing usable crawl ratio:
         tire factor  = fitted diameter / stock diameter
         adjusted CR  = raw CR / tire factor
       Related: Crawl Ratio (raw), Effective Gear Ratio (Tires), Tire Size. */
    const raw_cr=vd('cr_raw',80.0), stock_d=vd('cr_stock_d',31.0), new_d=vd('cr_new_d',37.0);
    const ok=[raw_cr,stock_d,new_d].every(Number.isFinite)&&raw_cr>0&&stock_d>0&&new_d>0;
    const factor = ok ? +(new_d/stock_d).toFixed(4) : NaN;
    const adj = ok ? +(raw_cr/factor).toFixed(2) : NaN;
    const delta = ok ? +(((adj/raw_cr)-1)*100).toFixed(1) : NaN;
    function useCase(cr){
      if(!Number.isFinite(cr)) return '';
      if(cr<25) return 'Daily driver / light trail — limited low-speed control';
      if(cr<40) return 'General 4WD — adequate for forest roads and mild obstacles';
      if(cr<55) return 'Moderate off-road — good throttle control on rough terrain';
      if(cr<85) return 'Rock crawling — strong low-speed control';
      return 'Competition crawling — very deep reduction';
    }
    const regear = ok && delta <= -15;
    return `${headerHTML('Tire-Adjusted Crawl Ratio','Fitting taller tires effectively raises your final drive and reduces usable crawl ratio. Tire factor = fitted diameter / stock diameter; adjusted crawl ratio = raw crawl ratio / tire factor. Use the Crawl Ratio calculator first if you need the raw figure.')}
    <div class="calc-body">
      ${field('Raw Crawl Ratio','cr_raw',80.0,':1')}
      ${field('Stock Tire Diameter','cr_stock_d',31.0,'in')}
      ${field('Fitted Tire Diameter','cr_new_d',37.0,'in')}
      ${ok?multiResult([
        {label:'Tire Factor',value:factor,unit:'x',precision:4},
        {label:'Adjusted Crawl Ratio',value:adj,unit:':1',precision:2},
        {label:'Change vs Stock',value:delta,unit:'%',precision:1}
      ]):`<div class="result-box"><div class="result-label">Validation required</div><div class="result-value">\u2014</div><div class="help-note">Crawl ratio and both tire diameters must be greater than zero.</div></div>`}
      ${ok?`<div style="margin-top:10px;font-size:13px;color:var(--muted)">Effective use case: ${useCase(adj)}</div>`:''}
      ${regear?`<div style="margin-top:8px;font-size:13px;color:var(--red)">Crawl ratio dropped ${Math.abs(delta)}% — regearing the axle is worth considering to recover low-speed control.</div>`:''}
      <div class="help-note">This adjusts the ratio only. Taller tires also raise the vehicle, change speedometer reading and increase driveline load — see Tire Size, Speedometer Calibration and Effective Gear Ratio (Tires).</div>
    </div>${calcFooter('Tire-Adjusted Crawl')}`;
  }

