tire_size(){
    const tw=vd('tw',245), ar=vd('ar',45), wr=vd('wr',17);
    const valid=tw>0 && ar>0 && wr>0;
    const sidewall=valid?(tw*ar/100)/25.4:0;
    const dia=valid?+(wr+2*sidewall).toFixed(3):0;
    const circ=valid?+(dia*Math.PI).toFixed(3):0;
