      ${field('Section Width','tw',245,'mm')}
      ${field('Aspect Ratio','ar',45,'%')}
      ${field('Wheel Diameter','wr',17,'in')}
      ${valid?multiResult([{label:'Sidewall Height',value:sidewall,unit:'in'},{label:'Overall Diameter',value:dia,unit:'in'},{label:'Circumference',value:circ,unit:'in'},{label:'Rev/Mile',value:rpmile,unit:'rev'}]):`<div class="result-box"><div class="result-value">Invalid tire dimensions</div></div>`}
      <div class="help-note">Feed the Overall Diameter above into Effective Gear Ratio (Tires) or Speedometer Calibration to see how this size affects gearing and speedometer accuracy.</div>
    </div>${calcFooter('Tire Size')}`;
  }

