air_density.live_full:
air_density(){
    const tempF=vd('temp3',59), presInHg=vd('pres',29.92), rh=vd('rh2',50);
    const valid=Number.isFinite(tempF)&&Number.isFinite(presInHg)&&Number.isFinite(rh)&&presInHg>0&&rh>=0&&rh<=100;
    const T=(tempF+459.67)*5/9;
    // Tetens saturation vapor pressure, Pa; adequate for normal shop/track conditions.
    const es=610.94*Math.exp((17.625*(tempF-32)/1.8)/((tempF-32)/1.8+243.04));
    const pv=valid?(rh/100)*es:0;
    const p=valid?presInHg*3386.389:0;
    const pd=Math.max(0,p-pv);
    const rhoKg=valid?(pd/(287.058*T)+pv/(461.495*T)):0;
    const rhoLbFt3=valid?+(rhoKg/16.0184634).toFixed(6):0;
    return `${headerHTML('Air Density','Calculates moist-air density from temperature, pressure and relative humidity. For a direct cross-check against Density Altitude, use the SAME station pressure used by the DA calculation (not the altimeter setting). Result is in lb/ft³ (pound-mass per cubic foot). Water vapor is less dense than dry air, so humidity slightly lowers density at fixed temperature and pressure.')}
    <div class="calc-body">
      ${field('Temperature','temp3',59,'°F')}
      ${field('Barometric Pressure','pres',29.92,'in Hg')}
      ${field('Relative Humidity','rh2',50,'%')}
      ${valid?resultHTML('Air Density',rhoLbFt3,'lb/ft³'):`<div class="result-box"><div class="result-value">Invalid atmospheric inputs</div></div>`}
    </div>${calcFooter('Air Density')}`;
  }

