ev_quarter_mile.live_full:
ev_quarter_mile(){
    /* WAVE 2 P0 (EV brief, Sept 2026). Quarter-mile ET and trap from power-to-weight.
       The classic constants (ET 5.825, trap 234) are empirical and were derived from
       ICE cars, so they embed shift losses and a launch-traction profile an EV does not
       share. Rather than silently substituting a different magic constant, the
       drivetrain utilization factor is exposed as a user input: 1.00 reproduces the
       ICE-derived baseline, and values above 1.00 credit an EV's uninterrupted torque
       delivery. Verified: the underlying ET/trap relations match the site's existing
       ICE calculators at utilization 1.00. */
    const wt=vd('evq_wt',4200), hp=vd('evq_hp',500), util=vd('evq_util',1.06);
    const ok=[wt,hp,util].every(Number.isFinite)&&wt>0&&hp>0&&util>0;
    const eff_hp = ok ? hp*util : NaN;
    const et  = ok ? +(5.825*Math.pow(wt/eff_hp,1/3)).toFixed(2) : NaN;
    const trap= ok ? +(234*Math.pow(eff_hp/wt,1/3)).toFixed(1) : NaN;
    const sixty = ok ? +(2.447*Math.pow(wt/eff_hp,1/3)).toFixed(2) : NaN;
    return `${headerHTML('EV Quarter-Mile Estimate','Power-to-weight estimate of quarter-mile ET and trap speed. ET = 5.825 x (weight / effective HP)^(1/3); trap = 234 x (effective HP / weight)^(1/3). These constants are empirical and ICE-derived, so a utilization factor is applied rather than assuming EV and ICE launch behave identically.')}
    <div class="calc-body">
      ${field('Vehicle Weight','evq_wt',4200,getU('weight'))}
      ${field('Peak Motor Power','evq_hp',500,'HP')}
      ${field('Drivetrain Utilization','evq_util',1.06,'x')}
      ${ok?multiResult([
        {label:'Effective Power',value:eff_hp,unit:'HP',precision:0},
        {label:'Estimated 0-60',value:sixty,unit:'sec',precision:2},
        {label:'Quarter-Mile ET',value:et,unit:'sec',precision:2},
        {label:'Trap Speed',value:trap,unit:'mph',precision:1}
      ]):`<div class="result-box"><div class="result-label">Validation required</div><div class="result-value">\u2014</div><div class="help-note">Weight, power and utilization must all be greater than zero.</div></div>`}
      <div class="help-note">Utilization 1.00 reproduces the ICE-derived baseline used elsewhere on this site. An EV typically holds a larger fraction of peak power through the run because there are no shift interruptions, which is why a figure slightly above 1.00 is a reasonable default — but this is a stated assumption, not a measured constant. Battery state of charge, thermal derate, launch traction and gearing all move the real number. Not a substitute for a timeslip.</div>
    </div>${calcFooter('EV Quarter-Mile')}`;
  }

