valve_spring_rate.live_full:
valve_spring_rate(){
    const d=vd('d_vs',0.148), n=vd('n_vs',8), D=vd('D_vs',0.9), seat=vd('seat_load',130), lift=vd('lift_vs',0.550);
    const G=11500000; // psi, steel spring shear modulus
    const valid=d>0 && n>0 && D>d && seat>=0 && lift>=0;
    const rate=valid?+((G*Math.pow(d,4))/(8*n*Math.pow(D,3))).toFixed(1):0;
    const open=valid?+(seat+rate*lift).toFixed(0):0;
    const index=valid?+(D/d).toFixed(2):0;
    return `${headerHTML('Valve Spring Rate','Basic helical compression-spring rate: k = Gd⁴/(8D³Nₐ). D is mean coil diameter and Nₐ is active coils. Open pressure is seat pressure plus spring rate × valve lift.')}
    <div class="calc-body">
      ${field('Wire Diameter','d_vs',0.148,'in')}
      ${field('Active Coils','n_vs',8,'')}
      ${field('Mean Coil Diameter','D_vs',0.9,'in')}
      ${field('Seat Pressure (installed)','seat_load',130,'lbs')}
      ${field('Valve Lift','lift_vs',0.550,'in')}
      ${valid?multiResult([{label:'Spring Rate',value:rate,unit:'lbs/in'},{label:'Open Pressure',value:open,unit:'lbs'},{label:'Spring Index',value:index,unit:':1'}]):`<div class="result-box"><div class="result-value">Invalid spring geometry</div><div class="help-note">Require D &gt; wire diameter and positive active-coil count.</div></div>`}
    </div>${calcFooter('Valve Spring Rate')}`;
  }

