winch_line_pull.live_full:
winch_line_pull(){
    /* WAVE 1 P1 (off-road brief, Sept 2026). Winch rating recommendation and
       mechanical-advantage-adjusted pull with snatch blocks.
       Minimum recommended line pull = GVWR × recovery difficulty multiplier.
       1.5x-2x GVWR is the widely used off-road recovery convention, not a
       physical law — stated explicitly rather than presented as derived.
       Mechanical advantage from blocks assumes a simple compounding double-line
       rig: MA = 2^N for N redirect blocks. Real MA depends on the actual rigging
       and friction losses reduce it in practice.
       Related: Recovery Point / Shackle Rating. */
    const gvwr=vd('wlp_gvwr',5500), mult=vd('wlp_mult',1.5), rated=vd('wlp_rated',9500), blocks=vd('wlp_blocks',0);
    const ok=[gvwr,mult,rated,blocks].every(Number.isFinite)&&gvwr>0&&mult>0&&rated>0&&blocks>=0;
    const minRec = ok ? +(gvwr*mult).toFixed(0) : NaN;
    const ma = ok ? Math.pow(2,Math.round(blocks)) : NaN;
    const effective = ok ? +(rated*ma).toFixed(0) : NaN;
    const meets = ok && rated >= minRec;
    return `${headerHTML('Winch Line Pull & Recovery Rating','Recommended minimum line pull = GVWR × recovery difficulty multiplier (1.5x is a common baseline; 2x or higher for mud, steep incline or single-tire recovery). Mechanical advantage with N snatch blocks in a simple doubled-line rig is modeled as 2^N — a stated rigging assumption, not a universal constant, and real-world friction loss will reduce it somewhat.')}
    <div class="calc-body">
      ${field('Vehicle GVWR','wlp_gvwr',5500,'lb')}
      ${field('Recovery Difficulty Multiplier','wlp_mult',1.5,'x')}
      ${field('Winch Rated Line Pull','wlp_rated',9500,'lb')}
      ${field('Number of Snatch Blocks','wlp_blocks',0,'count')}
      ${ok?multiResult([
        {label:'Recommended Minimum Line Pull',value:minRec,unit:'lb',precision:0},
        {label:'Mechanical Advantage',value:ma,unit:'x',precision:0},
        {label:'Effective Pull With Blocks',value:effective,unit:'lb',precision:0}
      ]):`<div class="result-box"><div class="result-label">Validation required</div><div class="result-value">—</div><div class="help-note">All values must be zero or greater, and GVWR, multiplier and rated pull must be greater than zero.</div></div>`}
      ${ok?`<div style="margin-top:10px;font-size:13px;color:${meets?'var(--muted)':'var(--red)'}">${meets?'Winch rating meets the recommended minimum for a direct pull.':'Winch rating is below the recommended minimum for a direct pull — a snatch block or a higher-rated winch is worth considering.'}</div>`:''}
      <div class="help-note">This is a planning estimate, not a rigging safety certification. Verify shackle, tree-strap and line ratings independently, and never exceed the lowest-rated component in the system. See Recovery Point / Shackle Rating for anchor-point capacity.</div>
    </div>${calcFooter('Winch Line Pull')}`;
  }

