e85_blend.live_full:
e85_blend(){
    const currentVol=vd('tank_gal',16), cur_e=vd('cur_e',10), target_e=vd('target_e',60), e85_pct=vd('e85_pct',75);
    const denom=e85_pct-target_e;
    let e85add=0, remove=0, status='';
    if(target_e===cur_e){
      status='Target already matches the current ethanol content.';
    } else if((target_e>cur_e && e85_pct>target_e) || (target_e<cur_e && e85_pct<target_e)){
      e85add=+(currentVol*(target_e-cur_e)/denom).toFixed(2);
      status='E85 amount is solved by volume-weighted ethanol balance.';
    } else if(target_e<cur_e){
      // E85 cannot lower an ethanol concentration. Solve for the amount of zero/low ethanol fuel
      // needed to dilute to the target, and report that as removal/replace guidance.
      const addLow = +(currentVol*(cur_e-target_e)/(target_e-(e85_pct))).toFixed(2);
      remove=Math.abs(addLow);
      status='Target is below the current ethanol content; E85 alone cannot achieve it. Remove fuel and replace with lower-ethanol fuel.';
    } else {
      status='Target is outside the achievable range for the selected E85 content.';
    }
    const stoich_e = +(14.7 - 5.7*(target_e/100)).toFixed(2);
    return `${headerHTML('E85 Ethanol Blend Calculator','Uses a volume-weighted ethanol balance. E85 content varies by season and fuel source, so enter the tested ethanol content when accuracy matters.')}
    <div class="calc-body">
      ${field('Current Fuel Volume','tank_gal',16,'gal')}
      ${field('Current Ethanol %','cur_e',10,'%')}
      ${field('Target Ethanol %','target_e',60,'%')}
      ${field('E85 Actual Ethanol Content','e85_pct',75,'%')}
      ${multiResult([
        {label:'E85 to Add',value:e85add>0?e85add:'—',unit:'gal'},
        {label:'Fuel to Remove / Replace',value:remove>0?remove:'—',unit:'gal'},
        {label:'Target Blend Stoich AFR',value:stoich_e,unit:':1'}
      ])}
      <div class="calc-note">${status} The simple top-off solve assumes the current fuel volume remains in the tank and only E85 is added.</div>
    </div>${calcFooter('E85 Blend')}`;
  }

