rc_watt_link.live_full:
rc_watt_link(){
    const L=vd('ph_len',40), travel=Math.abs(vd('ph_travel',3)), wb=vd('ph_wb',108);
    const valid=L>travel && L>0 && wb>0;
    // With a horizontal Panhard bar at ride height, lateral axle shift at vertical travel h:
    // Δx = L - sqrt(L² - h²). Rear-steer angle is atan(Δx / wheelbase).
    const lat=valid?+(L-Math.sqrt(L*L-travel*travel)).toFixed(4):0;
    const rear=valid?+(Math.atan(lat/wb)*180/Math.PI).toFixed(4):0;
    return `${headerHTML("Watt's Link vs Panhard Bar","A Watt's link constrains lateral axle motion. A Panhard bar follows an arc; for a horizontal bar, the lateral shift at vertical travel h is L − √(L²−h²).")}
    <div class="calc-body">
      <div style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:12px 14px;margin-bottom:16px;font-size:13px;color:var(--muted);line-height:1.6">
        <strong style="color:var(--red)">Watt's Link:</strong> Designed to keep the axle centered laterally.<br><br>
        <strong style="color:var(--red)">Panhard Bar:</strong> The axle moves laterally as the bar swings through its arc.
      </div>
      ${field('Panhard Bar Length','ph_len',40,'in')}
      ${field('Vertical Suspension Travel from Ride Height','ph_travel',3,'in')}
      ${field('Wheelbase (for rear-steer angle)','ph_wb',108,'in')}
      ${valid?multiResult([{label:'Lateral Axle Move',value:lat,unit:'in'},{label:'Induced Rear Steer',value:rear,unit:'°'}]):`<div class="result-box"><div class="result-value">Invalid geometry</div><div class="help-note">Bar length must exceed vertical travel and wheelbase must be positive.</div></div>`}
    </div>${calcFooter("Watt's Link")}`;
  }

