tire_size_comparison.live_full:
tire_size_comparison(){
    /* ADD (audit, 2026-09): the single most-requested missing piece from the
       tire cluster — compares two full tire sizes side by side (diameter,
       circumference, rev/mile, speedometer error) instead of making the user
       run Tire Size twice and do the subtraction by hand. */
    function decode(w,a,d){
      const valid=w>0&&a>0&&d>0;
      if(!valid) return null;
      const sidewall=(w*a/100)/25.4;
      const dia=+(d+2*sidewall).toFixed(3);
      const circ=+(dia*Math.PI).toFixed(3);
      const rpmile=+(63360/circ).toFixed(1);
      return {dia,circ,rpmile};
    }
    const ow=vd('tsc_ow',235), oa=vd('tsc_oa',75), od=vd('tsc_od',15);
    const nw=vd('tsc_nw',265), na=vd('tsc_na',70), nd=vd('tsc_nd',17);
    const oldT=decode(ow,oa,od), newT=decode(nw,na,nd);
    const valid=oldT!==null && newT!==null;
    const diaDeltaPct=valid?+(((newT.dia-oldT.dia)/oldT.dia)*100).toFixed(2):0;
    const clearanceDeltaIn=valid?+((newT.dia-oldT.dia)/2).toFixed(3):0;
    const speedoAtIndicated60=valid?+(60*(newT.dia/oldT.dia)).toFixed(1):0;
    const speedoErrorAt60=valid?+(speedoAtIndicated60-60).toFixed(1):0;
    return `${headerHTML('Tire Size Comparison','Runs the same decode as Tire Size for two tires at once and shows what actually changes: diameter delta, ground-clearance change, and how far off your speedometer reads at an indicated 60 mph. For the gear-ratio and full speedometer-calibration math using these diameters directly, continue to Effective Gear Ratio (Tires) or Speedometer Calibration.')}
    <div class="calc-body">
      <div class="gh-e1-fields">
        <div class="field"><label class="field-label" style="font-weight:700">Old Tire</label></div>
        ${field('Old Section Width','tsc_ow',235,'mm')}
        ${field('Old Aspect Ratio','tsc_oa',75,'%')}
        ${field('Old Wheel Diameter','tsc_od',15,'in')}
        <div class="field"><label class="field-label" style="font-weight:700">New Tire</label></div>
        ${field('New Section Width','tsc_nw',265,'mm')}
        ${field('New Aspect Ratio','tsc_na',70,'%')}
        ${field('New Wheel Diameter','tsc_nd',17,'in')}
      </div>
      ${valid?multiResult([
        {label:'Old Diameter',value:oldT.dia,unit:'in'},
        {label:'New Diameter',value:newT.dia,unit:'in'},
        {label:'Diameter Change',value:diaDeltaPct,unit:'%'},
        {label:'Ground Clearance Change',value:clearanceDeltaIn,unit:'in'},
        {label:'Old Rev/Mile',value:oldT.rpmile,unit:'rev'},
        {label:'New Rev/Mile',value:newT.rpmile,unit:'rev'},
        {label:'Actual Speed at Indicated 60',value:speedoAtIndicated60,unit:'mph'},
        {label:'Speedometer Error at 60',value:speedoErrorAt60,unit:'mph'}
      ]):`<div class="result-box"><div class="result-value">Invalid tire dimensions</div><div class="help-note">All widths, aspect ratios and wheel diameters must be greater than zero.</div></div>`}
      <div class="help-note">A positive diameter change means the new tire is taller. Ground clearance change assumes no suspension change. For the effect on your specific axle ratio, use Effective Gear Ratio (Tires) with these two diameters.</div>
    </div>${calcFooter('Tire Comparison')}`;
  }

