master_cylinder.live_full:
master_cylinder(){
    /* FIX (audit, 2026-09): this previously computed clamp force from pressure and
       bore, which duplicates the separate 'Brake Clamp Force' calculator and did not
       match this calculator's name. It now actually SIZES the master-cylinder bore
       from pedal force, pedal ratio and target line pressure, per its catalog name.
       IMPROVE (audit, 2026-09): added the reverse-solve direction — given an
       existing bore, what line pressure does it actually produce. */
    const mode_mc = GHM_STORAGE.get('mc_mode')||'bore';
    const pf=vd('mc_pedal',100), ratio=vd('mc_ratio',6);
    let body;
    if(mode_mc==='bore'){
      const pressure=vd('mc_pressure',1200);
      const valid=[pf,ratio,pressure].every(n=>Number.isFinite(n)&&n>0);
      const rodForce = valid ? pf*ratio : NaN;
      const area = valid ? rodForce/pressure : NaN;
      const bore = valid ? Math.sqrt(area*4/Math.PI) : NaN;
      body = `${field('Driver Pedal Force','mc_pedal',100,'lbf')}
      ${field('Pedal Ratio','mc_ratio',6,':1')}
      ${field('Target Line Pressure','mc_pressure',1200,'psi')}
      ${valid?multiResult([{label:'Pushrod Force',value:rodForce,unit:'lbf',precision:0},{label:'Required Piston Area',value:area,unit:'in\u00b2',precision:4},{label:'Required Bore Diameter',value:bore,unit:'in',precision:3}]):`<div class="result-box"><div class="result-label">Validation required</div><div class="result-value">\u2014</div><div class="help-note">Pedal force, pedal ratio and target pressure must all be greater than zero.</div></div>`}`;
    } else {
      const bore_mc=vd('mc_bore',0.798);
      const valid=[pf,ratio,bore_mc].every(n=>Number.isFinite(n)&&n>0);
      const rodForce = valid ? pf*ratio : NaN;
      const area = valid ? Math.PI*Math.pow(bore_mc,2)/4 : NaN;
      const pressure = valid ? rodForce/area : NaN;
      body = `${field('Driver Pedal Force','mc_pedal',100,'lbf')}
      ${field('Pedal Ratio','mc_ratio',6,':1')}
      ${field('Master Cylinder Bore','mc_bore',0.798,'in')}
      ${valid?multiResult([{label:'Pushrod Force',value:rodForce,unit:'lbf',precision:0},{label:'Piston Area',value:area,unit:'in\u00b2',precision:4},{label:'Resulting Line Pressure',value:pressure,unit:'psi',precision:0}]):`<div class="result-box"><div class="result-label">Validation required</div><div class="result-value">\u2014</div><div class="help-note">Pedal force, pedal ratio and bore must all be greater than zero.</div></div>`}`;
    }
    return `${headerHTML('Master Cylinder Sizing','Sizes master-cylinder bore from driver pedal force, pedal ratio and target line pressure — or, in reverse, tells you the line pressure an existing bore actually produces. For clamp force from a known bore, use Brake Clamp Force.')}
