throttle_body.live_full:
throttle_body(){
    /* REBUILT (audit 2026-09): the previous version tried to derive bore diameter
       directly from horsepower via sqrt((hp*2)/(cyl*0.58))/pi*2. There is no such
       closed-form relationship, and it returned 8.62 in (219 mm) for a 425 HP V8 --
       roughly 2.4x too large. Replaced with the derivable chain actually used to size
       a throttle body:
         1. airflow demand   CFM = CID * RPM * VE / 3456
         2. required area    A   = CFM * 144 / (v * 60)
         3. bore diameter    D   = 2 * sqrt(A / pi)
       Target velocity is a user input rather than a hidden constant. Verified against
       factory hardware: LS3 376ci/6600/90mm = 157 ft/s, SBC 350ci/6000/75mm = 181 ft/s. */
    const tb_cid=vd('tb_cid',426), tb_rpm=vd('tb_rpm',6000), tb_ve=vd('tb_ve',0.90),
          tb_vel=vd('tb_vel',175), tb_dia=vd('tb_dia',0);
    const ok=[tb_cid,tb_rpm,tb_ve,tb_vel].every(Number.isFinite)&&tb_cid>0&&tb_rpm>0&&tb_ve>0&&tb_vel>0;
    const cfm_tb = ok ? +(tb_cid*tb_rpm*tb_ve/3456).toFixed(1) : NaN;
    const area_tb = ok ? +(cfm_tb*144/(tb_vel*60)).toFixed(3) : NaN;
    const dia_in = ok ? +(2*Math.sqrt(area_tb/Math.PI)).toFixed(3) : NaN;
    const dia_mm = ok ? +(dia_in*25.4).toFixed(0) : NaN;
    const chk_vel = (tb_dia>0 && ok) ? +(cfm_tb*144/((Math.PI/4*tb_dia*tb_dia)*60)).toFixed(0) : null;
    return `${headerHTML('Throttle Body Sizing','Sizes the bore from actual airflow demand rather than a horsepower rule. CFM = CID x RPM x VE / 3456, required area = CFM x 144 / (velocity x 60), bore = 2*sqrt(A/pi). Factory throttle bodies typically run 150-200 ft/sec at peak; 175 is a sound starting target.')}
    <div class="calc-body">
      ${field('Displacement','tb_cid',426,'ci')}
      ${field('Peak RPM','tb_rpm',6000,'rpm')}
      ${field('Volumetric Efficiency','tb_ve',0.90,'')}
      ${field('Target Bore Velocity','tb_vel',175,'ft/sec')}
      ${ok?multiResult([
        {label:'Engine Airflow Demand',value:cfm_tb,unit:'CFM',precision:1},
        {label:'Required Bore Area',value:area_tb,unit:'in\u00b2',precision:3},
        {label:'Required Bore (inches)',value:dia_in,unit:'in',precision:3},
        {label:'Required Bore (metric)',value:dia_mm,unit:'mm',precision:0}
      ]):`<div class="result-box"><div class="result-label">Validation required</div><div class="result-value">\u2014</div><div class="help-note">Displacement, RPM, VE and target velocity must all be greater than zero.</div></div>`}
      <div style="border-top:1px solid var(--border);margin:16px 0;padding-top:16px">
        ${field('OR check a specific bore','tb_dia',0,'in')}
        ${chk_vel!==null?resultHTML('Velocity Through That Bore', chk_vel, 'ft/sec'):''}
      </div>
      <div class="help-note">This gives the bore area the engine's airflow actually requires. It is not a flow rating: two throttle bodies of the same diameter can flow differently depending on blade thickness, shaft blockage, bore taper and entry radius. Cross-check the final choice against the manufacturer's measured CFM.</div>
    </div>${calcFooter('Throttle Body')}`;
  }

