hp_from_specs.live_full:
hp_from_specs(){
    /* FIX (audit, 2026-09): fuel flow was computed by dividing volumetric
       airflow (CFM) directly by AFR, skipping the air-density conversion
       needed to turn a volume into a mass — this produced 6,390 HP at
       default inputs for a naturally aspirated 426ci engine, physically
       impossible. Airflow is now converted to a mass flow via air density
       before dividing by AFR, matching the deferred-issues suspected fix. */
    const cid2=vd('cid2',350), rpm_s=vd('rpm_s',6000), ve4=vd('ve4',0.85), bsfc_s=vd('bsfc_s',0.50), afr_s=vd('afr_s',12.5), air_density_s=vd('air_density_s',0.0765);
    const air_cfm=cid2*rpm_s*ve4/3456;
    const air_lbmin=air_cfm*air_density_s;
    const fuel_lbmin=air_lbmin/afr_s;
    const hp_s=fuel_lbmin*60/bsfc_s;
    return `${headerHTML('HP from CID / RPM / VE / BSFC / AFR','Estimates crank horsepower from estimated engine airflow and fuel consumption. Airflow (CFM) is converted to a mass flow using air density before applying AFR. Compression ratio is not a unique horsepower determinant, so it is intentionally not used in this airflow/BSFC model.')}
