      ${field('Displacement','cid2',350,'ci')}
      ${field('Peak RPM','rpm_s',6000,'RPM')}
      ${field('Volumetric Efficiency','ve4',0.85,'')}
      ${field('Air Density','air_density_s',0.0765,'lb/ft³')}
      ${field('BSFC','bsfc_s',0.50,'lb/hp-hr')}
      ${field('Target AFR','afr_s',12.5,':1')}
      ${multiResult([{label:'Estimated Airflow',value:air_cfm,unit:'CFM',precision:1},{label:'Air Mass Flow',value:air_lbmin,unit:'lb/min',precision:2},{label:'Fuel Flow',value:fuel_lbmin,unit:'lb/min',precision:2},{label:'Estimated HP',value:hp_s,unit:'HP',precision:0}])}
      <div class="help-note">This is an airflow/BSFC estimate. Actual power depends on combustion efficiency, pumping losses, fuel, spark, VE curve and many other factors.</div>
    </div>${calcFooter('HP from Specs')}`;
  }

