fuse_sizing.live_full:
fuse_sizing(){
    const amps_fs=vd('amps_fs',20), type_fs=sv('type_fs')||'continuous';
    /* FIX (audit 2026-09): the inrush factor was 0.5, which returned a fuse SMALLER
       than the continuous load (10A for a 20A motor) under a label reading "Min Fuse
       Rating". A motor/inrush circuit is never fused below its running current; it is
       fused above it with a time-delay element. 1.5x is the common convention -- the
       exact multiplier is a convention, but the direction is not. */
    const factor = {continuous:1.25, intermittent:1.0, inrush:1.5}[type_fs]||1.25;
    const fuse_a = +(amps_fs*factor).toFixed(0);
    const std_sizes = [1,2,3,5,7.5,10,15,20,25,30,35,40,50,60,70,80,100];
    const next_std = std_sizes.find(s=>s>=fuse_a)||100;
    return `${headerHTML('Fuse Sizing','Fuse = load amps × 125% for continuous loads. Pick next standard size up. Never upsize a fuse to "fix" a blowing fuse — find the cause.')}
    <div class="calc-body">
      ${field('Continuous Load Current','amps_fs',20,'A')}
      ${selectField('Load Type','type_fs',[{v:'continuous',l:'Continuous (×1.25)'},{v:'intermittent',l:'Intermittent (×1.0)'},{v:'inrush',l:'Motor Inrush (×1.5, time-delay)'}],type_fs)}
      ${multiResult([
        {label:'Min Fuse Rating',value:fuse_a,unit:'A'},
        {label:'Next Standard Size',value:next_std,unit:'A'}
      ])}
      <div class="help-note">Motor and other inrush loads should use a time-delay (slow-blow) fuse so the starting surge does not blow a correctly sized element. Never fuse an inrush circuit below its running current, and size the wire for the fuse — not the other way round.</div>
    </div>${calcFooter('Fuse Sizing')}`;
  }

